input.command:
source /tmp/explore/run.sh
rm -rf /tmp/explore/d1 && mkdir -p /tmp/explore/d1 && cd /tmp/explore/d1
cat > schema.hcl <<'EOF'
schema "main" {
}
table "users" {
  schema = schema.main
  column "id" {
    type = int
  }
  column "name" {
    null = true
    type = text
  }
  primary_key {
    columns = [column.id]
  }
}
EOF
run migrate diff --dev-url "sqlite://dev?mode=memory" --to "file://schema.hcl"
echo "### ls"
ls -la
find . -type f | sort
